+// Quiz data
+const quizData = [
+    {
+        id: 1,
+        question: "Which of these are compiled languages?",
+        helpText: "Compiled languages are translated into machine code before execution, as opposed to interpreted languages which are executed directly.",
+        options: [
+            { id: "q1-opt1", label: "Python" },
+            { id: "q1-opt2", label: "C++" },
+            { id: "q1-opt3", label: "JavaScript" },
+            { id: "q1-opt4", label: "Java" }
+        ],
+        correctAnswers: ["q1-opt2"] // C++ is compiled
+    },
+    {
+        id: 2,
+        question: "Which languages support object-oriented programming?",
+        options: [
+            { id: "q2-opt1", label: "Python" },
+            { id: "q2-opt2", label: "JavaScript" },
+            { id: "q2-opt3", label: "C" },
+            { id: "q2-opt4", label: "Java" }
+        ],
+        correctAnswers: ["q2-opt1", "q2-opt2", "q2-opt4"] // Python, JavaScript, Java
+    },
+    {
+        id: 3,
+        question: "Which of these are interpreted languages?",
+        options: [
+            { id: "q3-opt1", label: "Ruby" },
+            { id: "q3-opt2", label: "Go" },
+            { id: "q3-opt3", label: "Python" },
+            { id: "q3-opt4", label: "Rust" }
+        ],
+        correctAnswers: ["q3-opt1", "q3-opt3"] // Ruby and Python
+    }
+];
+
+// State management
+const state = {
+    answers: {}
+};
+
+// Initialize state with empty arrays for each question
+quizData.forEach(q => {
+    state.answers[`q${q.id}`] = [];
+});
+
+// Render the quiz
+function renderQuiz() {
+    const app = document.getElementById('app');
+    
+    app.innerHTML = `
+        <div class="quiz-container">
+            <div class="quiz-header">
+                <h1>Programming Languages Quiz</h1>
+                <p>Test your knowledge about programming languages</p>
+            </div>
+            <form id="quizForm">
+                ${quizData.map((q, idx) => renderQuestion(q, idx + 1)).join('')}
+                <button type="submit" class="submit-btn">Submit Quiz</button>
+                <div id="resultMessage" class="result-message"></div>
+            </form>
+        </div>
+    `;
+
+    // Attach event listeners
+    quizData.forEach(q => {
+        q.options.forEach(opt => {
+            const checkbox = document.getElementById(opt.id);
+            if (checkbox) {
+                checkbox.addEventListener('change', (e) => handleCheckboxChange(q.id, opt.id, e.target.checked));
+            }
+        });
+    });
+
+    const form = document.getElementById('quizForm');
+    form.addEventListener('submit', handleSubmit);
+}
+
+function renderQuestion(question, number) {
+    return `
+        <div class="form-field">
+            <div class="question-title">
+                <span class="question-number">${number}</span>
+                ${question.question}
+            </div>
+            ${question.helpText ? `
+                <div class="help-text">
+                    <span class="help-icon">ℹ️</span>
+                    <span>${question.helpText}</span>
+                </div>
+            ` : ''}
+            <div class="options">
+                ${question.options.map(opt => renderOption(opt, question.id)).join('')}
+            </div>
+        </div>
+    `;
+}
+
+function renderOption(option, questionId) {
+    const isChecked = state.answers[`q${questionId}`].includes(option.id);
+    return `
+        <div class="option">
+            <input 
+                type="checkbox" 
+                id="${option.id}" 
+                name="q${questionId}" 
+                value="${option.id}"
+                ${isChecked ? 'checked' : ''}
+            />
+            <label for="${option.id}">${option.label}</label>
+        </div>
+    `;
+}
+
+function handleCheckboxChange(questionId, optionId, isChecked) {
+    const questionKey = `q${questionId}`;
+    if (isChecked) {
+        if (!state.answers[questionKey].includes(optionId)) {
+            state.answers[questionKey].push(optionId);
+        }
+    } else {
+        state.answers[questionKey] = state.answers[questionKey].filter(id => id !== optionId);
+    }
+}
+
+function handleSubmit(e) {
+    e.preventDefault();
+
+    // Calculate score
+    let correct = 0;
+    let total = quizData.length;
+
+    quizData.forEach(q => {
+        const userAnswers = state.answers[`q${q.id}`].sort();
+        const correctAnswers = q.correctAnswers.sort();
+
+        // Check if arrays are equal
+        if (JSON.stringify(userAnswers) === JSON.stringify(correctAnswers)) {
+            correct++;
+        }
+    });
+
+    // Display result
+    const resultMessage = document.getElementById('resultMessage');
+    const percentage = Math.round((correct / total) * 100);
+
+    if (correct === total) {
+        resultMessage.className = 'result-message success';
+        resultMessage.textContent = `🎉 Perfect! You got all ${correct}/${total} questions correct!`;
+    } else {
+        resultMessage.className = 'result-message success';
+        resultMessage.textContent = `You got ${correct}/${total} questions correct (${percentage}%)`;
+    }
+}
+
+// Initialize the quiz on page load
+document.addEventListener('DOMContentLoaded', renderQuiz);
+
')

